package identity

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"errors"
	"strings"
	"testing"
)

// seedDeviceRow inserts one device-kind credential row directly (the
// pairing-owned shape, 2.2) so the session tests can assert isolation:
// session revocation and the reset cascade never touch device rows.
func seedDeviceRow(t *testing.T, s *Service, userID int64) {
	t.Helper()
	sum := sha256.Sum256([]byte("device-raw-token"))
	_, err := s.st.DB().ExecContext(context.Background(),
		`INSERT INTO credentials (kind, token_hash, user_id, label, created_at, expires_at)
VALUES ('device', ?, ?, 'tv', '2026-11-04T12:00:00Z', NULL)`,
		hex.EncodeToString(sum[:]), userID)
	if err != nil {
		t.Fatalf("seed device row: %v", err)
	}
}

// countCredentials counts credentials rows of one kind.
func countCredentials(t *testing.T, s *Service, kind string) int {
	t.Helper()
	var n int
	if err := s.st.DB().QueryRowContext(context.Background(),
		`SELECT COUNT(*) FROM credentials WHERE kind = ?`, kind).Scan(&n); err != nil {
		t.Fatalf("count credentials %q: %v", kind, err)
	}
	return n
}

// TestIdentitySessionLifecycle covers the session joint (task 3.3): mint
// with the right password → verify returns the user facts; wrong password
// and unknown user are ONE observable refusal (no enumeration); a disabled
// user's mint is refused; revoke kills exactly the presented session; a
// second session of the same user survives one session's revoke, and
// device rows are never touched by the session path.
func TestIdentitySessionLifecycle(t *testing.T) {
	ctx := context.Background()

	t.Run("mint_verify_roundtrip", func(t *testing.T) {
		s := openIdentityService(t)
		u, err := s.Create(ctx, "alia", "correct horse")
		if err != nil {
			t.Fatalf("Create: %v", err)
		}
		sess, err := s.MintSession(ctx, "  Alia  ", "correct horse")
		if err != nil {
			t.Fatalf("MintSession: %v", err)
		}
		if sess.Token == "" || sess.UserID != u.ID || sess.Username != "alia" || sess.Role != "user" {
			t.Fatalf("MintSession = %+v, want token + the created user's facts", sess)
		}
		got, err := s.VerifySession(ctx, sess.Token)
		if err != nil {
			t.Fatalf("VerifySession: %v", err)
		}
		if got.Token != "" {
			t.Fatalf("VerifySession token = %q, want empty (the caller holds it)", got.Token)
		}
		if got.UserID != u.ID || got.Username != "alia" || got.Role != "user" {
			t.Fatalf("VerifySession = %+v, want the user's principal facts", got)
		}
		if n := countCredentials(t, s, "session"); n != 1 {
			t.Fatalf("session rows = %d, want 1", n)
		}
	})

	t.Run("wrong_password_and_unknown_user_same_refusal", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "correct horse"); err != nil {
			t.Fatalf("Create: %v", err)
		}
		_, err := s.MintSession(ctx, "alia", "wrong horse")
		if !errors.Is(err, ErrAuth) {
			t.Fatalf("MintSession(wrong password) = %v, want ErrAuth", err)
		}
		_, err = s.MintSession(ctx, "nobody", "correct horse")
		if !errors.Is(err, ErrAuth) {
			t.Fatalf("MintSession(unknown user) = %v, want ErrAuth (same observable, no enumeration)", err)
		}
		if n := countCredentials(t, s, "session"); n != 0 {
			t.Fatalf("session rows = %d, want 0 after refusals", n)
		}
	})

	t.Run("disabled_user_mint_refused", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "pw"); err != nil {
			t.Fatalf("Create: %v", err)
		}
		if err := s.SetDisabled(ctx, "alia", true); err != nil {
			t.Fatalf("SetDisabled: %v", err)
		}
		_, err := s.MintSession(ctx, "alia", "pw")
		if !errors.Is(err, ErrAuth) {
			t.Fatalf("MintSession(disabled) = %v, want ErrAuth", err)
		}
	})

	t.Run("revoke_deletes_only_own_row", func(t *testing.T) {
		s := openIdentityService(t)
		u, err := s.Create(ctx, "alia", "pw")
		if err != nil {
			t.Fatalf("Create: %v", err)
		}
		seedDeviceRow(t, s, u.ID)
		first, err := s.MintSession(ctx, "alia", "pw")
		if err != nil {
			t.Fatalf("MintSession #1: %v", err)
		}
		second, err := s.MintSession(ctx, "alia", "pw")
		if err != nil {
			t.Fatalf("MintSession #2: %v", err)
		}
		if first.Token == second.Token {
			t.Fatalf("two mints share a token — not unguessable")
		}

		// Logout deletes only the presented session's row.
		if err := s.RevokeSession(ctx, first.Token); err != nil {
			t.Fatalf("RevokeSession: %v", err)
		}
		if _, err := s.VerifySession(ctx, first.Token); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("VerifySession(revoked) = %v, want the unknown-session (sql.ErrNoRows) error", err)
		}
		if _, err := s.VerifySession(ctx, second.Token); err != nil {
			t.Fatalf("VerifySession(survivor) = %v, want nil — revoke deletes only its own row", err)
		}
		if got, _ := s.VerifySession(ctx, second.Token); got.UserID != u.ID {
			t.Fatalf("survivor facts = %+v, want the same user", got)
		}
		if n := countCredentials(t, s, "session"); n != 1 {
			t.Fatalf("session rows = %d, want 1 (the survivor)", n)
		}
		// Isolation: the device-kind row is never session-revocable.
		if n := countCredentials(t, s, "device"); n != 1 {
			t.Fatalf("device rows = %d, want 1 — session paths never touch devices", n)
		}
	})

	t.Run("garbage_and_device_tokens_do_not_verify", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.VerifySession(ctx, "garbage"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("VerifySession(garbage) = %v, want unknown-session error", err)
		}
		if err := s.RevokeSession(ctx, "garbage"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("RevokeSession(garbage) = %v, want unknown-session error", err)
		}
	})

	t.Run("device_token_is_not_a_session", func(t *testing.T) {
		s := openIdentityService(t)
		u, err := s.Create(ctx, "alia", "pw")
		if err != nil {
			t.Fatalf("Create: %v", err)
		}
		seedDeviceRow(t, s, u.ID)
		// The device row's hash — presented as a session token — must not
		// resolve and must not be revocable through the session path.
		deviceHash := ""
		if err := s.st.DB().QueryRowContext(ctx,
			`SELECT token_hash FROM credentials WHERE kind = 'device'`).Scan(&deviceHash); err != nil {
			t.Fatalf("read device hash: %v", err)
		}
		if _, err := s.VerifySession(ctx, deviceHash); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("VerifySession(device hash) = %v, want unknown-session error", err)
		}
		if err := s.RevokeSession(ctx, deviceHash); !strings.Contains(err.Error(), "unknown session") {
			t.Fatalf("RevokeSession(device hash) = %v, want unknown-session error", err)
		}
		if n := countCredentials(t, s, "device"); n != 1 {
			t.Fatalf("device rows = %d, want 1 — kind guard held", n)
		}
	})
}

// TestIdentityPasswordResetRevokes covers the reset joint (task 3.3):
// HasUsers flips at the first create (the legacy-mode gate), and a password
// reset kills every session of that user while device rows survive.
func TestIdentityPasswordResetRevokes(t *testing.T) {
	ctx := context.Background()

	s := openIdentityService(t)
	has, err := s.HasUsers(ctx)
	if err != nil {
		t.Fatalf("HasUsers(empty): %v", err)
	}
	if has {
		t.Fatalf("HasUsers = true on a fresh store, want false (legacy mode)")
	}

	u, err := s.Create(ctx, "alia", "old pw")
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	seedDeviceRow(t, s, u.ID)
	first, err := s.MintSession(ctx, "alia", "old pw")
	if err != nil {
		t.Fatalf("MintSession #1: %v", err)
	}
	second, err := s.MintSession(ctx, "alia", "old pw")
	if err != nil {
		t.Fatalf("MintSession #2: %v", err)
	}

	has, err = s.HasUsers(ctx)
	if err != nil {
		t.Fatalf("HasUsers(after create): %v", err)
	}
	if !has {
		t.Fatalf("HasUsers = false after the first create, want true")
	}

	if err := s.ResetPassword(ctx, "alia", "new pw"); err != nil {
		t.Fatalf("ResetPassword: %v", err)
	}
	for name, tok := range map[string]string{"first": first.Token, "second": second.Token} {
		if _, err := s.VerifySession(ctx, tok); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("VerifySession(%s after reset) = %v, want unknown-session error (reset revoked it)", name, err)
		}
	}
	if n := countCredentials(t, s, "session"); n != 0 {
		t.Fatalf("session rows = %d, want 0 after reset", n)
	}
	if n := countCredentials(t, s, "device"); n != 1 {
		t.Fatalf("device rows = %d, want 1 — the reset cascade never touches devices", n)
	}

	// The new credential itself works (the rehash is 3.1's covered joint;
	// a fresh session mints and verifies against it).
	fresh, err := s.MintSession(ctx, "alia", "new pw")
	if err != nil {
		t.Fatalf("MintSession(new password): %v", err)
	}
	if _, err := s.VerifySession(ctx, fresh.Token); err != nil {
		t.Fatalf("VerifySession(fresh after reset): %v", err)
	}
}
